static void check(bool v,const char* label){if(!v)throw std::runtime_error(label);++checks;}
template<class F>static void rejects(F f,const char* label){bool yes=false;try{f();}catch(const std::exception&){yes=true;}check(yes,label);}
static QByteArray fileHash(const Path& p,std::size_t cap=64*1024*1024){return underlay::digest(underlay::readBounded(p,cap));}
static QJsonArray matrix(const pv::Affine& value){QJsonArray result;for(auto n:value.value)result.append(n);return result;}
static bool red(std::uint32_t pixel){return (pixel>>24)==255&&((pixel>>16)&255)>210&&((pixel>>8)&255)<70&&(pixel&255)<70;}
static void marker(const underlay::Prepared& p,const pv::Plan& plan){auto point=plan.forward.map({86,230});int x=int(std::floor(point.x)),y=int(std::floor(point.y));check(x>=0&&x<pv::Width&&y>=0&&y<pv::Height,"source marker is inside viewport");check(red(p.background[std::size_t(y)*underlay::Stride+x]),"actual colored marker follows authoritative transform");}
static QByteArray annotatedPdf(){QByteArray stream="BT /F1 18 Tf 50 610 Td (Existing colored annotation) Tj ET\n";QVector<QByteArray> objects{
 "<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
 "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 600 800] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R /Annots [6 0 R] >>",
 "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",QByteArray("<< /Length ")+QByteArray::number(stream.size())+" >>\nstream\n"+stream+"endstream",
 "<< /Type /Annot /Subtype /Highlight /Rect [48 603 310 633] /QuadPoints [48 633 310 633 48 603 310 603] /C [1 0 0] /CA 0.6 /F 4 >>"};QByteArray out="%PDF-1.7\n";QVector<qsizetype> offsets;for(int n=0;n<objects.size();++n){offsets.push_back(out.size());out+=QByteArray::number(n+1)+" 0 obj\n"+objects[n]+"\nendobj\n";}auto start=out.size();out+="xref\n0 "+QByteArray::number(objects.size()+1)+"\n0000000000 65535 f \n";for(auto offset:offsets)out+=QByteArray::number(offset).rightJustified(10,'0')+" 00000 n \n";out+="trailer\n<< /Size "+QByteArray::number(objects.size()+1)+" /Root 1 0 R >>\nstartxref\n"+QByteArray::number(start)+"\n%%EOF\n";return out;}
