 auto baseline=vs::readSet(docroot,{});auto baselinePath=vs::storagePath(docroot,baseline,0);QByteArray baselineFile,baselineJournal;
 {auto old=underlay::prepare(source,baselinePath,0,true,docroot);check(std::count_if(old.background.begin(),old.background.end(),red)>100,"default fitted imported PDF preserves color");check(old.metadata["legacyMeta"].toObject()["render"]=="reader-fit-footer100-mupdf1.28.3-threshold192-v1"&&old.binding==underlay::digest(QJsonDocument(old.metadata["legacyMeta"].toObject()).toJson(QJsonDocument::Compact)),"existing journal and annotation binding preserved through RGB presentation");auto current=reader::preparePdfView(source,docroot,0,baseline);check(old.metadata==current.metadata&&old.binding==current.binding&&old.background==current.background&&old.ink==current.ink,"absent entry preserves exact baseline preparation");check(current.metadata["schema"]==2,"baseline schema remains unchanged");baselineFile=fileHash(baselinePath/"prepared.bin");baselineJournal=fileHash(baselinePath/"annotations.ink");}
