 check(underlay::readBounded(docroot/"document.json",8192)==descriptorBytes&&fileHash(pdf)==sourceHash,"original descriptor and source retained");check(fileHash(baselinePath/"prepared.bin")==baselineFile&&fileHash(baselinePath/"annotations.ink")==baselineJournal,"new view preparation leaves baseline cache and journal unchanged");if(argc==3){Path output=argv[2];underlay::privateDirectory(output);underlay::atomicFile(output/"schema3-metadata.json",QJsonDocument(evidence).toJson(QJsonDocument::Indented));}check(temp.remove(),"owned helper data removed");std::cout<<"PREPARE_DOCUMENT_VIEW_PASS checks="<<checks<<" actual_view_renders="<<renders<<" baseline_exact=true source_hash_before_parser=true rgb32_roundtrip=true semantic_transform=true private_journal_replay=true physical=NOT_RUN\n";return 0;
